/**
 * Project Template Generator - Framework Alignment Templates
 * Generates compliant project structure templates and configurations
 */

export interface ProjectConfig {
  name: string;
  type: "application" | "library" | "service" | "documentation";
  description?: string;
  bookstackShelf?: string;
  uppEnabled?: boolean;
}

export class ProjectTemplate {
  /**
   * Generate _project.yaml template
   */
  public static generateProjectYaml(config: ProjectConfig): string {
    const timestamp = new Date().toISOString();

    return `# MosAIc Project Configuration
# Auto-generated project metadata for framework alignment

project:
  name: "${config.name}"
  type: "${config.type}"
  description: "${config.description || "Project description"}"
  version: "0.1.0"

# BookStack integration
bookstack:
  shelf: "${config.bookstackShelf || config.name}"
  sync_enabled: true
  auto_create_shelf: true
  
# Documentation structure
structure:
  version: "1.0"
  follows_upp: ${config.uppEnabled !== false}
  mandatory_folders:
    - "task-management"
    - "architecture" 
    - "api"
    - "operations"

# Framework compliance
framework:
  alignment_version: "1.0"
  project_equals_shelf: true
  anti_patterns_blocked: true
  
# Metadata
metadata:
  created: "${timestamp}"
  generator: "mosaic-cli"
  schema_version: "1.0"
  
# Task management (UPP methodology)
task_management:
  enabled: ${config.uppEnabled !== false}
  epic_prefix: "E"
  feature_prefix: "F"
  story_prefix: "S"
  task_prefix: "T"
  subtask_prefix: "ST"
  atomic_prefix: "A"
  
# CI/CD integration
ci_cd:
  structure_validation: true
  pre_commit_hooks: true
  alignment_checks: true
`;
  }

  /**
   * Generate MANDATORY_STRUCTURE.md template
   */
  public static generateMandatoryStructure(config: ProjectConfig): string {
    return `# ${config.name} - Mandatory Documentation Structure

This project follows the **MosAIc Framework Alignment** standards.

## 🏗️ Structure Overview

\`\`\`
docs/${config.name}/
├── task-management/          # UPP methodology (Epics, Features, Stories, Tasks)
│   ├── epics/
│   │   ├── active/          # Active epics
│   │   └── completed/       # Completed epics
│   ├── planning/            # Project planning documents
│   ├── active/              # Currently active tasks
│   └── completed/           # Completed tasks and retrospectives
├── architecture/            # System architecture and design
├── api/                     # API documentation and specifications
├── operations/              # Deployment, monitoring, and operations
└── _project.yaml           # Project metadata and configuration
\`\`\`

## 🎯 Framework Principles

### 1. Project = Shelf Rule
- **Every project gets its own BookStack shelf**
- Project name: \`${config.name}\`
- BookStack shelf: \`${config.bookstackShelf || config.name}\`
- No domain-based shelves allowed

### 2. Unified Path Structure
- All documentation under \`docs/${config.name}/\`
- Domain folders (architecture, api, operations) under project folder
- Task management follows UPP methodology

### 3. Anti-patterns Blocked
- ❌ \`docs/architecture/\` (domain at root)
- ❌ \`project/docs/\` (nested documentation)  
- ❌ Multiple MANDATORY_STRUCTURE.md files
- ❌ Mixed structure approaches

## 📋 UPP Task Hierarchy

\`\`\`
PROJECT (P)
├── EPIC (E.XXX)
│   ├── FEATURE (F.XXX.XX)
│   │   ├── STORY (S.XXX.XX.XX)
│   │   │   ├── TASK (T.XXX.XX.XX.XX)
│   │   │   │   ├── SUBTASK (ST.XXX.XX.XX.XX.XX)
│   │   │   │   │   └── ATOMIC (A.XXX.XX.XX.XX.XX.XX) [≤30 min]
\`\`\`

## 🔧 CLI Commands

\`\`\`bash
# Validate structure compliance
mosaic docs validate

# Migrate to unified structure  
mosaic docs migrate

# Check alignment status
mosaic docs check-alignment

# Initialize new project structure
mosaic docs init --project-name "${config.name}"
\`\`\`

## 📚 BookStack Integration

- **Shelf**: \`${config.bookstackShelf || config.name}\`
- **Auto-sync**: Enabled
- **Hierarchy**: Shelf → Book → Chapter → Page
- **Sync command**: \`mosaic bookstack sync\`

## ✅ Validation Rules

This structure is validated by:
- Pre-commit hooks
- CI/CD pipeline checks  
- Manual validation: \`mosaic docs validate\`
- Framework alignment enforcement

## 🚨 Important Notes

1. **DO NOT** create domain folders at \`docs/\` root
2. **DO NOT** nest documentation folders
3. **ALWAYS** use the project folder structure
4. **FOLLOW** UPP methodology for task management
5. **MAINTAIN** _project.yaml metadata

---

*Generated by MosAIc CLI - Framework Alignment v1.0*
`;
  }

  /**
   * Generate .gitignore additions for MosAIc projects
   */
  public static generateGitignoreAdditions(): string {
    return `
# MosAIc Framework
.mosaic/
.migration-backup-*/
docs/**/.DS_Store
docs/**/Thumbs.db

# Task management temporary files
docs/*/task-management/**/*.tmp
docs/*/task-management/**/*.bak

# BookStack sync cache
.bookstack-cache/
`;
  }

  /**
   * Generate README.md template for project documentation
   */
  public static generateDocumentationReadme(config: ProjectConfig): string {
    return `# ${config.name} Documentation

This documentation follows the **MosAIc Framework Alignment** standards.

## 📖 Documentation Structure

- **[Task Management](./task-management/)** - Project planning and UPP methodology
- **[Architecture](./architecture/)** - System design and architecture decisions  
- **[API](./api/)** - API documentation and specifications
- **[Operations](./operations/)** - Deployment, monitoring, and operational procedures

## 🎯 Framework Compliance

This project is **framework-aligned** and follows:
- Project = Shelf principle
- Unified documentation structure
- UPP task management methodology
- Anti-pattern prevention

## 🔧 Quick Commands

\`\`\`bash
# Validate structure
mosaic docs validate

# Sync to BookStack
mosaic bookstack sync

# Create new task
mosaic task create --epic E.001 --title "New Feature"
\`\`\`

## 📋 Project Metadata

- **Type**: ${config.type}
- **BookStack Shelf**: ${config.bookstackShelf || config.name}
- **UPP Enabled**: ${config.uppEnabled !== false ? "Yes" : "No"}
- **Framework Version**: 1.0

---

*This documentation is auto-synced with BookStack and validated by CI/CD.*
`;
  }

  /**
   * Generate complete directory structure
   */
  public static generateDirectoryStructure(
    config: ProjectConfig,
  ): DirectoryStructure {
    const basePath = `docs/${config.name}`;

    return {
      directories: [
        `${basePath}/task-management/epics/active`,
        `${basePath}/task-management/epics/completed`,
        `${basePath}/task-management/planning`,
        `${basePath}/task-management/active`,
        `${basePath}/task-management/completed`,
        `${basePath}/architecture`,
        `${basePath}/api`,
        `${basePath}/operations`,
      ],
      files: [
        {
          path: `${basePath}/_project.yaml`,
          content: this.generateProjectYaml(config),
        },
        {
          path: `${basePath}/MANDATORY_STRUCTURE.md`,
          content: this.generateMandatoryStructure(config),
        },
        {
          path: `${basePath}/README.md`,
          content: this.generateDocumentationReadme(config),
        },
        {
          path: `${basePath}/task-management/README.md`,
          content: this.generateTaskManagementReadme(),
        },
      ],
    };
  }

  /**
   * Generate task management README
   */
  private static generateTaskManagementReadme(): string {
    return `# Task Management

This folder follows the **UPP (Ultrathink Planning Protocol)** methodology.

## 📁 Structure

- \`epics/\` - Epic-level planning and tracking
  - \`active/\` - Currently active epics
  - \`completed/\` - Completed epics and retrospectives
- \`planning/\` - Project planning documents and roadmaps
- \`active/\` - Currently active tasks and subtasks
- \`completed/\` - Completed tasks and post-mortems

## 🎯 UPP Hierarchy

\`\`\`
EPIC (E.XXX) → FEATURE (F.XXX.XX) → STORY (S.XXX.XX.XX) → 
TASK (T.XXX.XX.XX.XX) → SUBTASK (ST.XXX.XX.XX.XX.XX) → 
ATOMIC (A.XXX.XX.XX.XX.XX.XX)
\`\`\`

## 🔧 CLI Usage

\`\`\`bash
# Create new epic
mosaic task create --type epic --title "User Authentication System"

# Create feature under epic
mosaic task create --parent E.001 --type feature --title "Login Flow"

# Assign task to agent
mosaic task assign T.001.01.01.01 --agent BE-BACKEND-BENJAMIN
\`\`\`

## 📋 Task States

- **PLANNING** - Initial planning phase
- **READY** - Ready for implementation
- **IN_PROGRESS** - Currently being worked on
- **REVIEW** - Under review
- **COMPLETED** - Finished and verified
- **BLOCKED** - Blocked by dependencies

---

*Managed by MosAIc Task Management System*
`;
  }
}

export interface DirectoryStructure {
  directories: string[];
  files: {
    path: string;
    content: string;
  }[];
}
